    return JSON.stringify(JSON.parse(encodeSnapshot(gameRef.current)), null, 2);
  }

  function resume(): void {
    if (!pausedRef.current || isWon(gameRef.current)) return;
    pausedRef.current = false;
    setPaused(false);
    clock.resumeAt(performance.now());
    publishStatus("Game resumed.");
  }

  function saveBestIfBeaten(won: GameState): void {
    const size = won.board.size;
    const previous = bestScoresRef.current[size];
    if (previous !== undefined && won.moves >= previous) return;
    const next = { ...bestScoresRef.current, [size]: won.moves };
    bestScoresRef.current = next;
    setBestScores(next);
    saveBestScores(next);
  }

  function activate(index: number): void {
    if (pausedRef.current || !visibleRef.current) return;
    const now = performance.now();
    const beforeTick = gameRef.current;
    if (beforeTick.started) tickAt(now);
    const before = gameRef.current;
    const next = activateCard(before, index);
    if (next === before) return;
    if (!before.started && next.started) {
      clock.begin(now);
    }
    updateGame(next);
    if (before.selection.kind === "one" && next.selection.kind === "mismatch") {
      announce("No match. Cards close after a short pause.");
    } else if (before.selection.kind === "one" && next.selection.kind === "closed") {
      if (isWon(next)) {
        setCelebration(true);
        saveBestIfBeaten(next);
        announce(`Pair found. All pairs found in ${next.moves} moves and ${formatElapsedTime(next.elapsedMs)}.`);
        clock.suspend();
      } else {
        const pairs = next.matched.length / 2;
        announce(`Pair found. ${pairs} ${pairs === 1 ? "pair" : "pairs"} matched.`);
      }
    }
  }

  return {
    game, paused, dealRevision, celebration, bestScores, notice,
    activate, newGame, restart, changeSize, loadBoard, loadSnapshot, exportSnapshot, resume,
  };
}
import { forwardRef, useEffect, useImperativeHandle, useRef, useState } from "react";
import type { CSSProperties, KeyboardEvent, MouseEvent } from "react";
import { SELECTION_KIND, type GameState } from "../types.ts";
import { Card } from "./Card.tsx";

export type BoardHandle = Readonly<{ focusRemembered: () => void }>;
export type BoardProps = Readonly<{
  game: GameState;
  dealRevision: number;
  paused: boolean;
  onActivate: (index: number) => void;
}>;

type CardState = "closed" | "revealed" | "matched";

function cardState(game: GameState, index: number): CardState {
  if (game.matched.includes(index)) return "matched";
  switch (game.selection.kind) {
    case SELECTION_KIND.CLOSED: return "closed";
    case SELECTION_KIND.ONE: return game.selection.index === index ? "revealed" : "closed";
    case SELECTION_KIND.MISMATCH:
      return game.selection.first === index || game.selection.second === index ? "revealed" : "closed";
  }
}

function nextIndex(index: number, size: number, count: number, key: string): number {
  const column = index % size;
  switch (key) {
    case "ArrowLeft": return column > 0 ? index - 1 : index;
    case "ArrowRight": return column + 1 < size ? index + 1 : index;
    case "ArrowUp": return index >= size ? index - size : index;
    case "ArrowDown": return index + size < count ? index + size : index;
    default: return index;
  }
}

function isArrow(key: string): boolean {
  return key === "ArrowLeft" || key === "ArrowRight" || key === "ArrowUp" || key === "ArrowDown";
}

export const Board = forwardRef<BoardHandle, BoardProps>(function Board(props, ref) {
  const [focusIndex, setFocusIndex] = useState(0);
  const focusIndexRef = useRef(0);
  const buttons = useRef<(HTMLButtonElement | null)[]>([]);
  const scrollArea = useRef<HTMLDivElement | null>(null);
  const count = props.game.board.deck.length;
  const size = props.game.board.size;

  useEffect(() => {
    focusIndexRef.current = 0;
    setFocusIndex(0);
  }, [props.dealRevision]);

  useImperativeHandle(ref, () => ({
    focusRemembered() {
      buttons.current[focusIndexRef.current]?.focus();
    },
  }), []);

  function rememberFocus(index: number): void {
    focusIndexRef.current = index;
    setFocusIndex((current) => current === index ? current : index);
    const area = scrollArea.current;
    const button = buttons.current[index];
    if (area === null || button === null || button === undefined) return;
    const areaRect = area.getBoundingClientRect();
    const cardRect = button.getBoundingClientRect();
    const viewportLeft = areaRect.left + area.clientLeft + 6;
    const viewportTop = areaRect.top + area.clientTop + 6;
    const viewportRight = areaRect.left + area.clientLeft + area.clientWidth - 6;
    const viewportBottom = areaRect.top + area.clientTop + area.clientHeight - 6;
    if (cardRect.left < viewportLeft) area.scrollLeft -= viewportLeft - cardRect.left;
    else if (cardRect.right > viewportRight) area.scrollLeft += cardRect.right - viewportRight;
    if (cardRect.top < viewportTop) area.scrollTop -= viewportTop - cardRect.top;
    else if (cardRect.bottom > viewportBottom) area.scrollTop += cardRect.bottom - viewportBottom;
  }

  function moveFocus(event: KeyboardEvent<HTMLButtonElement>, index: number): void {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey || !isArrow(event.key)) return;
    event.preventDefault();
    const destination = nextIndex(index, size, count, event.key);
    rememberFocus(destination);
    buttons.current[destination]?.focus();
  }

  function activate(event: MouseEvent<HTMLButtonElement>, index: number): void {
    if (event.button !== 0 || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    if (props.paused) return;
    props.onActivate(index);
  }

  const available = 44 + 6 * (size - 1);
  const style: CSSProperties = {
    gridTemplateColumns: `repeat(${size}, minmax(44px, min(88px, calc((min(100vw, 1120px) - ${available}px) / ${size}))))`,
  };

  return (
    <div className="board-scroll" role="region" aria-label="Card board" ref={scrollArea}>
      <div className="board-grid" role="group" aria-label="Memory cards" style={style}>
        {props.game.board.deck.map((faceId, index) => {
          const state = cardState(props.game, index);
          return (
            <Card
              key={index}
              index={index}
              size={size}
              faceId={state === "closed" ? null : faceId}
              state={state}
              tabIndex={focusIndex === index ? 0 : -1}
              onClick={(event) => activate(event, index)}
              onKeyDown={(event) => moveFocus(event, index)}
              onFocus={() => rememberFocus(index)}
              ref={(element) => { buttons.current[index] = element; }}
            />
          );
        })}
      </div>
    </div>
  );
});
import { forwardRef } from "react";
import type { KeyboardEvent, MouseEvent, ReactNode } from "react";
import { faceName, CardBack, FaceArtwork } from "./faces.tsx";

export type CardProps = Readonly<{
  index: number;
  size: number;
  faceId: number | null;
  state: "closed" | "revealed" | "matched";
  tabIndex: 0 | -1;
  onClick: (event: MouseEvent<HTMLButtonElement>) => void;
  onKeyDown: (event: KeyboardEvent<HTMLButtonElement>) => void;
  onFocus: () => void;
}>;

function accessibleName(index: number, size: number, faceId: number | null, state: CardProps["state"]): string {
  const row = Math.floor(index / size) + 1;
  const column = index % size + 1;
  if (faceId === null) return `Row ${row}, column ${column}, closed`;
  return `Row ${row}, column ${column}, ${faceName(faceId)}, ${state}`;
}

function artwork(faceId: number | null): ReactNode {
  if (faceId === null) return <CardBack />;
  return <FaceArtwork faceId={faceId} />;
}

export const Card = forwardRef<HTMLButtonElement, CardProps>(function Card(props, ref) {
  const label = accessibleName(props.index, props.size, props.faceId, props.state);
  return (
    <button
      type="button"
      ref={ref}
      className={`card card-${props.state}`}
      aria-label={label}
      aria-disabled={props.state === "matched" ? "true" : undefined}
      tabIndex={props.tabIndex}
      onClick={props.onClick}
      onKeyDown={props.onKeyDown}
      onFocus={props.onFocus}
    >
      {artwork(props.faceId)}
      {props.state === "matched" ? <span className="match-check" aria-hidden="true">✓</span> : null}
    </button>
  );
});

