/work/src/game/controls/controls.css.content:
.game-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}

.size-control, .form-row { display: grid; min-width: 0; gap: 6px; }
.size-control label, .form-row label { color: var(--secondary); font-size: 14px; }

button, select, input, textarea {
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--panel);
}

button, select { min-height: 44px; padding: 8px 12px; }
button { cursor: pointer; }
button:hover { border-color: var(--text); }
.primary-button { border-color: var(--cyan); color: var(--cyan); font-weight: 700; }
.deal-buttons, .control-row, .reproduction-actions { display: flex; flex-wrap: wrap; gap: 8px; }

.reproduction-area { margin-top: 16px; }
.reproduction-details { overflow: hidden; border: 1px solid #292F45; border-radius: 8px; background: var(--panel); }
.reproduction-details summary { min-height: 44px; padding: 8px 12px; cursor: pointer; font-weight: 700; }
.reproduction-content { display: grid; gap: 16px; padding: 12px; border-top: 1px solid #292F45; }
.control-row input { flex: 1 1 180px; min-width: 0; padding: 8px 12px; }
.form-row textarea { display: block; width: 100%; min-width: 0; padding: 8px 12px; resize: vertical; }
.control-status { min-height: 24px; margin: 8px 0 0; color: var(--secondary); font-size: 14px; }

@media (max-width: 520px) {
  .game-controls { align-items: stretch; }
  .deal-buttons button { flex: 1; }
}

/work/src/styles.css.content:
@import url("./game/board/board.css");
@import url("./game/controls/controls.css");

:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  line-height: 24px;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  --page: #090B14;
  --panel: #141827;
  --back: #1B2034;
  --face: #111625;
  --text: #F4F6FF;
  --secondary: #B8BDD2;
  --border: #757C9A;
  --focus: #FFFFFF;
  --green: #8BEA7D;
  --cyan: #63E7FF;
}

* { box-sizing: border-box; }

html { min-width: 320px; background: var(--page); }

body {
  min-width: 320px;
  min-height: 100vh;
  margin: 0;
  overflow-x: hidden;
  background: var(--page);
  color: var(--text);
}

button, input, select, textarea { font: inherit; }

button, select, input, textarea { color: var(--text); }

button:focus-visible, select:focus-visible, input:focus-visible, textarea:focus-visible, summary:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.game-shell {
  width: 100%;
  max-width: 1120px;
  min-width: 0;
  margin: 0 auto;
  padding: 24px 16px 32px;
}

.hero { margin-bottom: 24px; }
.eyebrow { margin: 0 0 4px; color: var(--cyan); font-size: 14px; font-weight: 700; letter-spacing: 0.12em; }
.hero h1 { margin: 0; font-size: 24px; line-height: 32px; font-weight: 760; }
.lede { margin: 4px 0 0; color: var(--secondary); }

.status-panel {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  margin: 16px 0;
}

.status-panel p {
  min-width: 0;
  margin: 0;
  padding: 8px 12px;
  border: 1px solid #292F45;
  border-radius: 8px;
  background: var(--panel);
}

.status-panel strong { font-variant-numeric: tabular-nums; }
.status-panel .pause-note { color: var(--secondary); }

.win-banner {
  margin: 16px 0;
  padding: 12px 16px;
  border: 1px solid var(--green);
  border-radius: 8px;
  background: var(--panel);
}

.win-banner h2 { margin: 0; font-size: 18px; line-height: 24px; }
.win-banner p { margin: 4px 0 0; color: var(--secondary); }
.win-celebrate { animation: win-pulse 600ms ease-out 1; }

@keyframes win-pulse {
  0% { transform: scale(0.99); box-shadow: 0 0 0 0 rgb(139 234 125 / 35%); }
  45% { transform: scale(1.015); box-shadow: 0 0 0 8px rgb(139 234 125 / 0%); }
  100% { transform: scale(1); box-shadow: 0 0 0 0 rgb(139 234 125 / 0%); }
}

.board-help { margin: 8px 0 24px; color: var(--secondary); font-size: 14px; }
.live-announcement { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }

@media (max-width: 520px) {
  .game-shell { padding-top: 16px; }
  .hero { margin-bottom: 16px; }
  .status-panel { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (prefers-reduced-motion: reduce) {
  .win-celebrate { animation: none; }
}

