/work/src/game/controls/status.css.content:
.status-panel {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  margin: 16px 0;
}

.status-panel p {
  min-width: 0;
  margin: 0;
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--panel);
  color: var(--secondary);
  font-size: 14px;
}

.status-panel strong { color: var(--text); font-size: 16px; font-variant-numeric: tabular-nums; }
.status-panel .pause-note { color: var(--secondary); }

.win-banner {
  margin: 16px 0;
  padding: 12px 16px;
  border: 1px solid var(--green);
  border-radius: 8px;
  background: var(--panel);
}

.win-banner h2 { margin: 0; font-size: 18px; line-height: 24px; }
.win-banner p { margin: 4px 0 0; color: var(--secondary); font-size: 14px; }
.win-celebrate { animation: win-pulse 600ms ease-out 1; }

@keyframes win-pulse {
  0% { transform: scale(0.99); box-shadow: 0 0 0 0 rgb(139 234 125 / 35%); }
  45% { transform: scale(1.015); box-shadow: 0 0 0 8px rgb(139 234 125 / 0%); }
  100% { transform: scale(1); box-shadow: 0 0 0 0 rgb(139 234 125 / 0%); }
}

@media (max-width: 520px) {
  .status-panel { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (prefers-reduced-motion: reduce) {
  .win-celebrate { animation: none; }
}

