  --green: #8BEA7D;
  --cyan: #63E7FF;
}

* { box-sizing: border-box; }

html { background: var(--page); }

body {
  min-height: 100vh;
  margin: 0;
  overflow-x: hidden;
  background: var(--page);
  color: var(--text);
}

button, input, select, textarea { font: inherit; }

button, select, input, textarea { color: var(--text); }

button:focus-visible, select:focus-visible, input:focus-visible, textarea:focus-visible, summary:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.game-shell {
  width: 100%;
  max-width: 1120px;
  min-width: 0;
  margin: 0 auto;
  padding: 16px;
}

.hero { margin-bottom: 24px; }
.eyebrow { margin: 0 0 4px; color: var(--cyan); font-size: 14px; font-weight: 700; letter-spacing: 0.12em; }
.hero h1 { margin: 0; font-size: 24px; line-height: 32px; font-weight: 760; }
.lede { margin: 4px 0 0; color: var(--secondary); font-size: 14px; }

.board-help { margin: 8px 0 24px; color: var(--secondary); font-size: 14px; }
.live-announcement { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }

.primary-button { border: 1px solid var(--cyan); color: var(--cyan); font-weight: 700; }
.primary-button:hover { border-color: var(--cyan); }
.game-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}

.size-control { display: grid; min-width: 0; gap: 6px; }
.size-control label { color: var(--secondary); font-size: 14px; }
.deal-buttons { display: flex; flex-wrap: wrap; gap: 8px; }

@media (max-width: 520px) {
  .game-controls { align-items: flex-start; }
  .deal-buttons { width: 100%; }
  .deal-buttons button { flex: 1; }
}

