import { chromium } from '@playwright/test';
const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({ viewport: { width: 360, height: 800 } });
await context.setOffline(true);
const page = await context.newPage();
page.setDefaultTimeout(5000);
const network = [];
page.on('request', request => { if (request.url().startsWith('http')) network.push(request.url()); });
await page.goto('file:///work/dist/index.html');
await page.getByRole('heading', { name: 'Neon Pairs' }).waitFor();
await page.screenshot({ path: '/tmp/neon-pairs-mobile.png', fullPage: true });
await page.getByText('Reproduce a game', { exact: true }).click();
const cards = page.locator('.card');
const hiddenName = await cards.first().getAttribute('aria-label');
await page.getByLabel('Board code').fill(' np1-4-1 ');
await page.getByRole('button', { name: 'Load board' }).click();
await cards.nth(0).click();
const revealedName = await cards.nth(0).getAttribute('aria-label');
await cards.nth(1).click();
const miss = await page.locator('[role=status]').innerText();
const before = await cards.nth(1).getAttribute('aria-label');
await page.waitForTimeout(830);
const after = await cards.nth(1).getAttribute('aria-label');
await page.getByRole('button', { name: 'Export snapshot' }).click();
const snapshot = await page.getByLabel('Snapshot JSON').inputValue();
await page.getByRole('button', { name: 'Load snapshot' }).click();
const paused = await page.getByRole('button', { name: 'Resume' }).isVisible();
const beforePausedClick = await cards.nth(2).getAttribute('aria-label');
await cards.nth(2).click();
const afterPausedClick = await cards.nth(2).getAttribute('aria-label');
await page.getByRole('button', { name: 'Resume' }).click();
const resumeFocus = await page.evaluate(() => document.activeElement?.getAttribute('aria-label'));
await page.getByLabel('Grid size').selectOption('16');
await cards.first().focus();
await page.keyboard.press('ArrowRight');
const arrowFocus = await page.evaluate(() => document.activeElement?.getAttribute('aria-label'));
await page.locator('.card').last().focus();
const layout16 = await page.evaluate(() => {
 const board = document.querySelector('.board-scroll');
 const card = document.querySelector('.card');
 const last = document.querySelector('.card:last-child');
 const boardRect = board?.getBoundingClientRect();
 const lastRect = last?.getBoundingClientRect();
 return { page: document.documentElement.scrollWidth, viewport: innerWidth, boardClient: board?.clientWidth, boardScroll: board?.scrollWidth, card: card?.getBoundingClientRect().width, lastVisible: !!boardRect && !!lastRect && lastRect.right <= boardRect.right && lastRect.bottom <= boardRect.bottom };
});
await page.setViewportSize({ width: 1280, height: 800 });
await page.getByLabel('Grid size').selectOption('4');
await page.screenshot({ path: '/tmp/neon-pairs-desktop.png', fullPage: true });
console.log(JSON.stringify({hiddenName, revealedName, miss, mismatchBefore: before, mismatchAfter: after, snapshotValid: JSON.parse(snapshot).version === 1, paused, pausedInputBlocked: beforePausedClick === afterPausedClick, resumeFocus, arrowFocus, layout16, network}));
await browser.close();
NODE","workdir":"/work","yield_time_ms":30000,"max_output_tokens":3000}));

