      return current;
    }
    const last = lastTimeRef.current;
    if (last === null) {
      lastTimeRef.current = now;
      return current;
    }
    const elapsed = now - last + fractionalMsRef.current;
    const wholeMs = Math.floor(elapsed);
    fractionalMsRef.current = elapsed - wholeMs;
    lastTimeRef.current = now;
