    begin(now) {
      lastTimeRef.current = now;
      fractionalMsRef.current = 0;
    },
    suspend() {
      lastTimeRef.current = null;
    },
    resumeAt(now) {
      const current = gameRef.current;
      lastTimeRef.current = current.started && !isWon(current) && visibleRef.current ? now : null;
    },
  };
}
