    gameRef.current = next;
    setGame(next);
  }

  const clock = useActiveClock(gameRef, pausedRef, visibleRef, updateGame);

  function announce(text: string): void {
    setNotice((current) => ({ text, revision: current.revision + 1 }));
  }

