    return clock.tickAt(now);
  }

  useEffect(() => {
    visibleRef.current = !document.hidden;
    if (!visibleRef.current) clock.suspend();
    let active = true;
    const revision = dealRevision;
    const isCurrentDeal = () => active && dealRevisionRef.current === revision;
    function onVisibilityChange(): void {
      if (!isCurrentDeal()) return;
      const now = performance.now();
      if (document.hidden) {
        if (visibleRef.current) tickAt(now);
        visibleRef.current = false;
        clock.suspend();
      } else {
        visibleRef.current = true;
        const current = gameRef.current;
