import type { Page } from "@playwright/test";

export async function startBoard(page: Page, code = "np1-4-1"): Promise<void> {
  await page.goto("/");
  await page.getByText("Reproduce a game", { exact: true }).click();
  const boardCode = page.getByLabel("Board code");
  await boardCode.fill(code);
  await page.getByRole("button", { name: "Load board" }).click();
}

export function cardAt(page: Page, index: number) {
  return page.locator(".board-grid > button").nth(index);
}

export async function advance(page: Page, milliseconds: number): Promise<void> {
  await page.clock.runFor(milliseconds);
}

/work/e2e/timing.spec.ts.content:
import { expect, test } from "@playwright/test";
import { advance, cardAt, startBoard } from "./helpers.ts";

test("closes a mismatch exactly 800 active milliseconds after an off-tick reveal", async ({ page }) => {
  await page.clock.install();
  await startBoard(page);
  await cardAt(page, 0).click();
  await advance(page, 23);
  await cardAt(page, 1).click();
  await expect(page.locator(".card-revealed")).toHaveCount(2);
  await advance(page, 799);
  await expect(page.locator(".card-revealed")).toHaveCount(2);
  await advance(page, 1);
  await expect(page.locator(".card-revealed")).toHaveCount(0);
  await expect(page.getByText("Moves: 1", { exact: true })).toBeVisible();
});

test("pauses the mismatch countdown while hidden and restores its exact remainder", async ({ page }) => {
  await page.clock.install();
  await startBoard(page);
  await cardAt(page, 0).click();
  await cardAt(page, 1).click();
  await advance(page, 300);
  await page.evaluate(() => {
    Object.defineProperty(document, "hidden", { configurable: true, value: true });
    document.dispatchEvent(new Event("visibilitychange"));
  });
  await advance(page, 5_000);
  await expect(page.locator(".card-revealed")).toHaveCount(2);
  await page.evaluate(() => {
    Object.defineProperty(document, "hidden", { configurable: true, value: false });
    document.dispatchEvent(new Event("visibilitychange"));
  });
  await advance(page, 499);
  await expect(page.locator(".card-revealed")).toHaveCount(2);
  await advance(page, 1);
  await expect(page.locator(".card-revealed")).toHaveCount(0);
});

test("keeps an imported mismatch paused until Resume then uses its saved remainder", async ({ page }) => {
  await page.clock.install();
  await startBoard(page);
  await cardAt(page, 0).click();
  await cardAt(page, 1).click();
  await advance(page, 500);
  await page.getByRole("button", { name: "Export snapshot" }).click();
  const snapshot = JSON.parse(await page.getByLabel("Snapshot JSON").inputValue()) as { selection: { remainingMs: number } };
  expect(snapshot.selection.remainingMs).toBe(300);
  await page.getByLabel("Snapshot JSON").fill(JSON.stringify(JSON.parse(await page.getByLabel("Snapshot JSON").inputValue())));
  await page.getByRole("button", { name: "Load snapshot" }).click();
  await expect(page.getByRole("button", { name: "Resume" })).toBeVisible();
  await cardAt(page, 4).click();
  await expect(page.getByText("Moves: 1", { exact: true })).toBeVisible();
  await advance(page, 5_000);
  await expect(page.locator(".card-revealed")).toHaveCount(2);
  await page.getByRole("button", { name: "Resume" }).click();
  await advance(page, 299);
  await expect(page.locator(".card-revealed")).toHaveCount(2);
  await advance(page, 1);
  await expect(page.locator(".card-revealed")).toHaveCount(0);
});

